p=Path('t15_residual_fast.cpp');s=p.read_text().split('void solve(){')[0];s+='''int main(int argc,char**argv){if(argc!=4)return 2;ifstream in(argv[1],ios::binary);out.open(argv[2],ios::binary);fail.open(argv[3]);unsigned char raw[26];while(in.read((char*)raw,26)){req.clear();for(int j=0;j<26;j+=2)req.emplace_back(raw[j],raw[j+1]);blocks={{0},{13},{21},{31}};for(auto[a,b]:req)blocks.push_back({a,b});nodes=0;timeout=false;route={{0,0}};prepare();bool ok=fastdfs(0,((1u<<blocks.size())-1)&~1u,allEntries&~3ull);total++;totalNodes+=nodes;maxNodes=max(maxNodes,nodes);if(ok){positive++;out.write((char*)raw,26);for(auto[k,rev]:route){auto b=blocks[k];if(rev)reverse(b.begin(),b.end());for(int v:b)out.put(char(v));}}else{if(timeout)unknown++;else negative++;fail<<total-1<<' '<<(timeout?"UNKNOWN":"EXHAUSTED")<<'\\n';}}cout<<"{\\"total\\":"<<total<<",\\"positive\\":"<<positive<<",\\"unknown\\":"<<unknown<<",\\"negative\\":"<<negative<<",\\"nodes\\":"<<totalNodes<<",\\"max_nodes\\":"<<maxNodes<<"}\\n";}''';Path('t15_core24_raw_residual.cpp').write_text(s)
